/* G2 (Normal Academic) Sec 2 generators, part B: Ch5 Algebraic Fractions, Ch6 Proportion, Ch7 Quadrilaterals and Other
   Polygons, Ch8 Congruence and Similarity, Ch9 Pythagoras' Theorem.
   Sec 2 banks are 10 multiple choice + 10 typed (each bank has 5 word problems). Style follows the Shing Lee N(A) practice
   exercises and the G2 chapter worksheets in the Shinglee folder (SLWS). Every answer is computed from the question's own numbers. */
'use strict';
module.exports = function(H){
  const {N, mcq, gcd, sp, sg} = H;
  const dol = v => '\\$' + (Number.isInteger(+v) ? sp(+v) : (+v).toFixed(2));
  const deg = v => v + '°';
  const U = s => v => H.numText(v) + ' ' + s;
  const cm = U('cm'), m = U('m'), cm2 = U('cm²'), km = U('km');
  const TRIPLES = [[3, 4, 5], [5, 12, 13], [8, 15, 17], [7, 24, 25], [20, 21, 29]];
  const tri = r => { const t = r.pick(TRIPLES), k = t[2] * 4 > 100 ? 1 : r.int(1, 4); return t.map(v => v * k); };
  const gyms = [];

  /* ---- Algebraic fractions ---- */
  gyms.push({id: 'G2.2.algebraic-fractions.1', plain: [
    r => { const a = r.int(2, 6), b = r.int(1, 8), x = r.int(2, 12); return N(`Simplify $\\dfrac{${a}x + ${a * b}}{${a}}$ and find its value when $x = ${x}$.`, x + b, `${a}x + ${a * b} = ${a}(x + ${b}), so the fraction simplifies to x + ${b}. When x = ${x}, the value is ${x + b}.`, {wr: [x + a * b, a * x + b, x + b + 1, x * b]}); },
    r => { const a = r.int(2, 5), b = r.int(2, 5); if (a === b) return null; return N(`$\\dfrac{x}{${a}} + \\dfrac{x}{${b}} = \\dfrac{kx}{${a * b}}$. Find $k$.`, a + b, `The common denominator is ${a * b}: ${b}x/${a * b} + ${a}x/${a * b} = ${a + b}x/${a * b}, so k = ${a + b}.`, {wr: [a * b, b - a, a + b + 1, 2]}); },
    r => { const t = r.int(1, 4), x = 6 * t + 1; return N(`Find the value of $\\dfrac{x + 2}{3} + \\dfrac{x - 1}{2}$ when $x = ${x}$.`, (x + 2) / 3 + (x - 1) / 2, `(${x} + 2)/3 = ${(x + 2) / 3} and (${x} − 1)/2 = ${(x - 1) / 2}. The sum is ${(x + 2) / 3 + (x - 1) / 2}.`, {wr: [(x + 2) / 3, (x - 1) / 2, x + 1, (x + 2) / 3 + (x - 1) / 2 + 1]}); },
    r => { const c = r.int(1, 8), a = r.int(1, 6); const x = a + 2 * c; return N(`Solve $\\dfrac{x + ${a}}{2} = x - ${c}$.`, x, `Multiply both sides by 2: x + ${a} = 2x − ${2 * c}, so x = ${a + 2 * c}.`, {wr: [c, a + c, x + 1, 2 * c - a]}); },
    r => { const m = r.int(2, 5), a = r.int(2, 5), c = r.int(2, 4), b = m * c; return N(`Find the value of $\\dfrac{${a}x}{${b}} \\div \\dfrac{${a}x}{${c}}$.`, c / b, `Dividing by a fraction means multiplying by its reciprocal: (${a}x/${b}) × (${c}/${a}x) = ${c}/${b} = ${c / b}.`, {wr: [b / c, c * b, 1, a]}); },
    r => { const a = r.int(2, 9), x = r.int(2, 10); return N(`Simplify $\\dfrac{x^2 + ${a}x}{x}$ and find its value when $x = ${x}$.`, x + a, `x² + ${a}x = x(x + ${a}), so the fraction is x + ${a}. When x = ${x}, it equals ${x + a}.`, {wr: [x * x + a, x * x + a * x, x + a + 1, a]}); },
    r => { const a = r.int(2, 9), x = r.int(a + 1, a + 10); return N(`Simplify $\\dfrac{x^2 - ${a * a}}{x - ${a}}$ and find its value when $x = ${x}$.`, x + a, `x² − ${a * a} = (x − ${a})(x + ${a}), so the fraction is x + ${a}. When x = ${x}, it equals ${x + a}.`, {wr: [x - a, x * x - a * a, x + a + 1, a]}); },
    r => { const k = r.int(2, 9), a = r.int(2, 9), x = r.int(2, 9); return N(`Find the value of $\\dfrac{${k}x + ${k * a}}{${k}(x + ${a})}$ when $x = ${x}$.`, 1, `The numerator is ${k}(x + ${a}), the same as the denominator, so the fraction equals 1 for any x.`, {wr: [k, x + a, 0, k * a]}); },
    r => { const a = r.int(2, 9), b = r.int(2, 9); return mcq(r, `Simplify $\\dfrac{${a * b}x}{${a * (b + 1)}}$.`, `$\\dfrac{${b}x}{${b + 1}}$`, [`$\\dfrac{${b}x}{${b}}$`, `$\\dfrac{x}{${b + 1}}$`, `$\\dfrac{${a * b}}{${b + 1}}$`, `$\\dfrac{${b + 1}x}{${b}}$`], `Divide the numerator and denominator by ${a}: ${a * b}x ÷ ${a} = ${b}x and ${a * (b + 1)} ÷ ${a} = ${b + 1}.`); },
    r => { const a = r.int(2, 8); return mcq(r, `Simplify $\\dfrac{x^2 + ${a}x}{x}$.`, `$x + ${a}$`, [`$x^2 + ${a}$`, `$${a}x$`, `$x + ${a}x$`, `$${a}$`], `Take out the common factor x in the numerator: x(x + ${a}) ÷ x = x + ${a}.`); }
  ], word: [
    r => { const n = r.pick([4, 5, 6, 8]), b = r.int(2, 5), x = r.int(8, 30); return N(`A total of $(${n}x + ${n * b})$ dollars is shared equally among ${n} friends. Each friend gets $(x + ${b})$ dollars. How much does each friend get when $x = ${x}$, in dollars?`, x + b, `Each share is (${n}x + ${n * b}) ÷ ${n} = x + ${b}. When x = ${x}, each gets ${x + b} dollars.`, {wr: [n * x + n * b, x + n * b, x + b + n, (x + b) * n], f: dol}); },
    r => { const p = r.pick([[3, 6, 2], [4, 12, 3], [6, 12, 4], [10, 15, 6], [12, 24, 8], [15, 30, 10]]); return N(`Pipe A can fill a tank in ${p[0]} hours and pipe B can fill it in ${p[1]} hours. How many hours do they take to fill the tank together?`, p[2], `In one hour they fill 1/${p[0]} + 1/${p[1]} = 1/${p[2]} of the tank, so the time is ${p[2]} hours.`, {wr: [p[0] + p[1], p[0], (p[0] + p[1]) / 2, p[2] + 1]}); },
    r => { const a = r.int(3, 9), x = r.int(5, 20); return N(`A rectangle has area $(x^2 + ${a}x)$ cm² and width $x$ cm. Find its length when $x = ${x}$, in cm.`, x + a, `Length = (x² + ${a}x) ÷ x = x + ${a} = ${x + a} cm.`, {wr: [x * x + a * x, x + a * x, a, x + a + 1], f: cm}); },
    r => { const k = r.int(3, 6), a = r.int(2, 5), x = r.int(4, 20); return N(`A car travels $(${k * 3}x + ${k * 3 * a})$ km in 3 hours. Its speed is $(${k}x + ${k * a})$ km/h. Find its speed when $x = ${x}$, in km/h.`, k * x + k * a, `Speed = distance ÷ time = (${k * 3}x + ${k * 3 * a}) ÷ 3 = ${k}x + ${k * a}. When x = ${x}, it is ${k * x + k * a} km/h.`, {wr: [3 * k * x + 3 * k * a, k * x + a, k * x, k * (x + a) + 3]}); },
    r => { const a = r.pick([2, 3, 4, 5]), b = r.pick([6, 8, 10, 12]), x = (a * b / gcd(a, b)) * r.int(1, 3); return N(`Ali takes $\\dfrac{x}{${a}}$ minutes to walk to school and Ben takes $\\dfrac{x}{${b}}$ minutes. Find how many minutes longer Ali takes when $x = ${x}$.`, x / a - x / b, `Ali: ${x}/${a} = ${x / a}. Ben: ${x}/${b} = ${x / b}. Difference = ${x / a - x / b} minutes.`, {wr: [x / a + x / b, x / a, x / b, x / a - x / b + 1]}); }
  ]});

  /* ---- Direct proportion ---- */
  gyms.push({id: 'G2.2.proportion.1', plain: [
    r => { const k = r.int(2, 9), x1 = r.int(2, 6), x2 = r.int(7, 15); return N(`$y$ is directly proportional to $x$. When $x = ${x1}$, $y = ${k * x1}$. Find $y$ when $x = ${x2}$.`, k * x2, `y = kx. k = ${k * x1} ÷ ${x1} = ${k}. When x = ${x2}, y = ${k} × ${x2} = ${k * x2}.`, {wr: [k * x2 + k, x2 + k * x1 - x1, k * x1, k * x2 - k]}); },
    r => { const k = r.int(2, 9), x1 = r.int(2, 8), x2 = r.int(2, 15); return N(`$y$ is directly proportional to $x$. When $y = ${k * x1}$, $x = ${x1}$. Find $x$ when $y = ${k * x2}$.`, x2, `k = ${k * x1} ÷ ${x1} = ${k}. x = ${k * x2} ÷ ${k} = ${x2}.`, {wr: [k * x2, x2 + 1, x2 - 1, k]}); },
    r => { const k = r.int(2, 9), x1 = r.int(3, 9); return N(`$y$ is directly proportional to $x$, and $y = ${k * x1}$ when $x = ${x1}$. Find the constant of proportionality.`, k, `k = y ÷ x = ${k * x1} ÷ ${x1} = ${k}.`, {wr: [k * x1, x1, k + 1, k - 1]}); },
    r => { const k = r.int(2, 5), x1 = r.int(2, 4), x2 = r.int(5, 9); return N(`$y$ is directly proportional to $x^2$. When $x = ${x1}$, $y = ${k * x1 * x1}$. Find $y$ when $x = ${x2}$.`, k * x2 * x2, `y = kx². k = ${k * x1 * x1} ÷ ${x1 * x1} = ${k}. When x = ${x2}, y = ${k} × ${x2 * x2} = ${k * x2 * x2}.`, {wr: [k * x2, k * x2 * x2 + k, (k * x1 * x1) * x2, k * x1 * x1]}); },
    r => { const k = r.int(2, 9), p = r.int(2, 6), q = r.int(7, 14), s = r.int(15, 25); return N(`In a table, $y$ is directly proportional to $x$. When $x$ is ${p}, $y$ is ${k * p}. When $x$ is ${q}, $y$ is ${k * q}. What is $y$ when $x$ is ${s}?`, k * s, `y ÷ x = ${k} each time, so y = ${k} × ${s} = ${k * s}.`, {wr: [k * s + k, k * (s - 1), k * p + k * q, s + k]}); },
    r => { const k = r.int(3, 9), a = r.int(2, 6), b = r.int(7, 15); return N(`If $y = ${k}x$, find the value of $y$ when $x = ${a + b}$.`, k * (a + b), `y = ${k} × ${a + b} = ${k * (a + b)}.`, {wr: [k + a + b, k * a + b, k * (a + b) + k, k * b]}); },
    r => { const k = r.int(2, 6), x1 = r.int(2, 5), x2 = r.int(6, 12); return N(`$y$ is directly proportional to $x$. When $x$ increases from ${x1} to ${x2}, $y$ increases from ${k * x1} to ${k * x2}. Find the increase in $y$.`, k * (x2 - x1), `Increase = ${k * x2} − ${k * x1} = ${k * (x2 - x1)}.`, {wr: [k * x2, x2 - x1, k, k * (x2 - x1) + k]}); },
    r => mcq(r, 'If $y$ is directly proportional to $x$, which of the following is true?', '$\\dfrac{y}{x}$ is a constant', ['$xy$ is a constant', '$y + x$ is a constant', '$y - x$ is a constant'], 'Direct proportion means y = kx, so y ÷ x is always the same constant k.'),
    r => { const k = r.int(2, 9), x = r.int(2, 8); return mcq(r, `$y$ is directly proportional to $x$ and $y = ${k * x}$ when $x = ${x}$. Which equation connects $x$ and $y$?`, `$y = ${k}x$`, [`$y = \\dfrac{${k}}{x}$`, `$y = x + ${k * x - x}$`, `$y = ${k * x}x$`, `$y = ${x}x$`], `k = ${k * x} ÷ ${x} = ${k}, so y = ${k}x.`); }
  ], word: [
    r => { const p = r.int(2, 9), a = r.int(3, 6), b = r.int(7, 15); return N(`${a} kg of rice cost \\$${a * p}. How much do ${b} kg of rice cost, in dollars? (The cost is directly proportional to the mass.)`, p * b, `1 kg costs ${a * p} ÷ ${a} = ${p} dollars. ${b} kg cost ${p * b} dollars.`, {wr: [p * b + p, a * p + b, p * a * b, (a * p) / b], f: dol}); },
    r => { const v = r.int(3, 9), a = r.int(2, 5), b = r.int(6, 12); return N(`A car uses ${a * v} litres of petrol for ${a * 100} km. How many litres does it use for ${b * 100} km?`, b * v, `${a * v} litres for ${a * 100} km is ${v} litres per 100 km. For ${b * 100} km: ${b * v} litres.`, {wr: [b * v + v, a * v + b, b * 100, v * a * b]}); },
    r => { const w = r.int(8, 18), a = r.int(3, 6), b = r.int(7, 12); return N(`Ali earns \\$${a * w} for ${a} hours of work. At the same rate, how much does he earn for ${b} hours, in dollars?`, w * b, `Rate = ${a * w} ÷ ${a} = ${w} per hour. For ${b} hours: ${w * b} dollars.`, {wr: [w * b + w, a * w + b, w * a * b, a * w], f: dol}); },
    r => { const f = r.int(2, 5), a = r.int(2, 4), b = r.int(6, 12); return N(`A recipe uses ${a * f} cups of flour to make ${a * 4} biscuits. How many cups of flour are needed to make ${b * 4} biscuits?`, f * b, `Flour per 4 biscuits = ${f} cups. ${b * 4} biscuits need ${f} × ${b} = ${f * b} cups.`, {wr: [f * b + f, a * f + b, f * b * 4, f * a * b]}); },
    r => { const s = r.int(2, 6), a = r.int(3, 6), b = r.int(7, 12); return N(`A machine prints ${a * s * 10} pages in ${a} minutes. How many pages does it print in ${b} minutes?`, s * 10 * b, `Pages per minute = ${s * 10}. In ${b} minutes: ${s * 10 * b} pages.`, {wr: [s * 10 * b + s * 10, a * s * 10 + b, s * 10 * a * b, a * s * 10]}); }
  ]});

  /* ---- Inverse proportion ---- */
  gyms.push({id: 'G2.2.proportion.2', plain: [
    r => { const k = r.pick([12, 24, 36, 48, 60]), d = [2, 3, 4, 6, 8, 12].filter(v => k % v === 0 && v < k), x1 = r.pick(d), x2 = r.pick(d.filter(v => v !== x1)); if (x2 === undefined) return null; return N(`$y$ is inversely proportional to $x$. When $x = ${x1}$, $y = ${k / x1}$. Find $y$ when $x = ${x2}$.`, k / x2, `xy = ${k}. When x = ${x2}, y = ${k} ÷ ${x2} = ${k / x2}.`, {wr: [k * x2, k / x2 + 1, x1 * x2, k / x1]}); },
    r => { const k = r.pick([24, 36, 48, 60, 72]), x1 = r.pick([2, 3, 4, 6]), y2 = r.pick([2, 3, 4, 6, 8, 12]); if (k % x1 || k % y2 || k / x1 === y2) return null; return N(`$y$ is inversely proportional to $x$. When $x = ${x1}$, $y = ${k / x1}$. Find $x$ when $y = ${y2}$.`, k / y2, `xy = ${k}. When y = ${y2}, x = ${k} ÷ ${y2} = ${k / y2}.`, {wr: [k * y2, k / y2 + 1, x1 * y2, k / x1]}); },
    r => { const x1 = r.int(2, 8), y1 = r.int(3, 12); return N(`$y$ is inversely proportional to $x$, and $y = ${y1}$ when $x = ${x1}$. Find the constant $k$ in $xy = k$.`, x1 * y1, `k = xy = ${x1} × ${y1} = ${x1 * y1}.`, {wr: [x1 + y1, y1 / x1 | 0, x1 * y1 + x1, x1 * y1 - y1]}); },
    r => { const w1 = r.pick([4, 6, 8, 12]), d1 = r.pick([6, 9, 10, 12, 15]), w2 = r.pick([2, 3, 4, 6, 9]); if ((w1 * d1) % w2 || w1 === w2) return null; return N(`${w1} workers can finish a job in ${d1} days. How many days will ${w2} workers take, working at the same rate?`, w1 * d1 / w2, `Total work = ${w1} × ${d1} = ${w1 * d1} worker-days. ${w2} workers need ${w1 * d1 / w2} days.`, {wr: [w1 * d1 * w2, d1 + w1 - w2, w1 * d1 / w2 + 1, d1]}); },
    r => { const v1 = r.pick([40, 60, 80]), t1 = r.pick([3, 4, 6]), v2 = r.pick([30, 40, 48, 60, 80, 120]); if ((v1 * t1) % v2 || v1 === v2) return null; return N(`A journey takes ${t1} hours at ${v1} km/h. How many hours does it take at ${v2} km/h?`, v1 * t1 / v2, `Distance = ${v1} × ${t1} = ${v1 * t1} km. Time at ${v2} km/h = ${v1 * t1} ÷ ${v2} = ${v1 * t1 / v2} hours.`, {wr: [v1 * t1 * v2, t1 + v1 - v2, t1, v1 * t1 / v2 + 1]}); },
    r => { const k = r.pick([36, 72, 144]), x1 = r.pick([2, 3, 4]), x2 = r.pick([6, 9, 12]); if (k % (x1 * x1) || k % (x2 * x2)) return null; return N(`$y$ is inversely proportional to $x^2$. When $x = ${x1}$, $y = ${k / (x1 * x1)}$. Find $y$ when $x = ${x2}$.`, k / (x2 * x2), `x²y = ${k}. When x = ${x2}, y = ${k} ÷ ${x2 * x2} = ${k / (x2 * x2)}.`, {wr: [k / x2, k / (x1 * x1), k * x2 * x2, k / (x2 * x2) + 1]}); },
    r => { const k = r.pick([60, 72, 90, 120]), x = r.pick([3, 4, 5, 6, 8, 9, 10, 12, 15]); if (k % x) return null; return N(`If $xy = ${k}$, find $y$ when $x = ${x}$.`, k / x, `y = ${k} ÷ ${x} = ${k / x}.`, {wr: [k * x, k - x, k / x + 1, k / x - 1]}); },
    r => mcq(r, 'If $y$ is inversely proportional to $x$, which of the following is true?', '$xy$ is a constant', ['$\\dfrac{y}{x}$ is a constant', '$y + x$ is a constant', 'when $x$ doubles, $y$ also doubles'], 'Inverse proportion means y = k/x, so xy = k is constant, and doubling x halves y.'),
    r => { const k = r.pick([12, 24, 36]), x = r.pick([2, 3, 4]); return mcq(r, `$y$ is inversely proportional to $x$ and $y = ${k / x}$ when $x = ${x}$. Which equation connects $x$ and $y$?`, `$y = \\dfrac{${k}}{x}$`, [`$y = ${k / x / x}x$`, `$y = ${k}x$`, `$y = x + ${k / x - x}$`, `$y = \\dfrac{x}{${k}}$`], `k = xy = ${x} × ${k / x} = ${k}, so y = ${k}/x.`); }
  ], word: [
    r => { const n = r.pick([6, 8, 12]), d = r.pick([3, 4, 5, 6, 9]), m = r.pick([2, 3, 4, 9, 12, 18]); if ((n * d) % m || m === n) return null; return N(`${n} children share some sweets and get ${d} sweets each. If ${m} children share the same sweets instead, how many sweets does each child get?`, n * d / m, `Total sweets = ${n} × ${d} = ${n * d}. Each of ${m} children gets ${n * d / m}.`, {wr: [n * d * m, n * d / m + 1, d, n * d / m - 1]}); },
    r => { const t1 = r.pick([6, 8, 10, 12]), p = r.pick([2, 3, 4]), q = r.pick([4, 6, 8, 12]); if ((t1 * p) % q || p === q) return null; return N(`${p} taps fill a pool in ${t1} hours. How many hours do ${q} identical taps take to fill the pool?`, t1 * p / q, `Total = ${p} × ${t1} = ${p * t1} tap-hours. ${q} taps need ${p * t1 / q} hours.`, {wr: [t1 * p * q, t1 + p - q, t1, p * t1 / q + 1]}); },
    r => { const a = r.pick([3, 4, 5, 6]), d = r.pick([10, 12, 15, 20]), b = r.pick([2, 5, 6, 8, 10]); if ((a * d) % b || a === b) return null; return N(`${a} painters take ${d} days to paint a block of flats. How many days do ${b} painters take at the same rate?`, a * d / b, `Total = ${a} × ${d} = ${a * d} painter-days. ${b} painters need ${a * d / b} days.`, {wr: [a * d * b, a + d - b, d, a * d / b + 1]}); },
    r => { const v = r.pick([45, 60, 90]), t = r.pick([2, 3, 4, 6]), v2 = r.pick([36, 45, 60, 90, 120]); if ((v * t) % v2 || v === v2) return null; return N(`A bus travels from Town A to Town B in ${t} hours at ${v} km/h. How long does the return trip take at ${v2} km/h, in hours?`, v * t / v2, `Distance = ${v * t} km. Time = ${v * t} ÷ ${v2} = ${v * t / v2} hours.`, {wr: [v * t * v2, t, v * t / v2 + 1, v - v2]}); },
    r => { const c = r.pick([24, 36, 48, 60]), a = r.pick([2, 3, 4, 6]), b = r.pick([8, 9, 12]); if (c % a || c % b) return null; return N(`A prize of \\$${c * 10} is shared equally among ${a} winners. If there were ${b} winners instead, how much would each get, in dollars?`, c * 10 / b, `Each of ${b} winners gets ${c * 10} ÷ ${b} = ${c * 10 / b} dollars.`, {wr: [c * 10 / a, c * 10 / b + 10, c * 10 * b, c * 10 / b - 10], f: dol}); }
  ]});

  /* ---- Quadrilaterals ---- */
  gyms.push({id: 'G2.2.quadrilaterals-and-other-polygons.1', plain: [
    r => { const a = r.int(40, 140); return N(`In a parallelogram, one angle is ${a}°. Find the angle next to it (adjacent angle), in degrees.`, 180 - a, `Adjacent angles in a parallelogram add up to 180°: 180 − ${a} = ${180 - a}.`, {wr: [a, 360 - a, 90, 180 + a - 90], f: deg}); },
    r => { const a = r.int(40, 140); return N(`In a parallelogram, one angle is ${a}°. Find the angle opposite to it, in degrees.`, a, 'Opposite angles of a parallelogram are equal.', {wr: [180 - a, 360 - a, 90, a + 10], f: deg}); },
    r => { const a = r.int(50, 100), b = r.int(60, 110), c = r.int(70, 120); if (a + b + c >= 340) return null; return N(`Three angles of a quadrilateral are ${a}°, ${b}° and ${c}°. Find the fourth angle, in degrees.`, 360 - a - b - c, `Angles in a quadrilateral add up to 360°: 360 − ${a} − ${b} − ${c} = ${360 - a - b - c}.`, {wr: [180 - a - b - c > 0 ? 180 - a - b - c : a + b + c - 180, a + b + c, 360 - a - b], f: deg}); },
    r => { const B = r.int(70, 120), C = r.int(40, 90), A = 360 - 2 * B - C; if (A <= 20) return null; return N(`ABCD is a kite with AB = AD and CB = CD. Angle B = ${B}° and angle C = ${C}°. Find angle A, in degrees.`, A, `Angle D = angle B = ${B}°. Angle A = 360 − ${B} − ${B} − ${C} = ${A}.`, {wr: [360 - B - C, 180 - C, 360 - B - C - A, A + 10], f: deg}); },
    r => { const a = r.int(50, 130); return N(`In a trapezium ABCD, AB is parallel to DC. Angle A = ${a}°. Find angle D, in degrees.`, 180 - a, `Angles on the same side between parallel lines add up to 180°: 180 − ${a} = ${180 - a}.`, {wr: [a, 360 - a, 90, 180 + a - 90], f: deg}); },
    r => { const s = r.int(4, 15); return N(`A rhombus has sides of ${s} cm. Find its perimeter, in cm.`, 4 * s, `A rhombus has 4 equal sides: 4 × ${s} = ${4 * s} cm.`, {wr: [2 * s, s * s, 4 * s + 4, 3 * s], f: cm}); },
    r => { const d = r.int(8, 30); return N(`The diagonal AC of a rectangle ABCD is ${d} cm. Find the length of the other diagonal BD, in cm.`, d, 'The diagonals of a rectangle are equal in length.', {wr: [d / 2, 2 * d, d + 2, d - 2], f: cm}); },
    r => { const a = r.int(20, 80) * 2; return N(`A rhombus has an angle of ${a}° at one corner. The diagonal through that corner bisects the angle. Find the angle between the diagonal and a side, in degrees.`, a / 2, `The diagonal bisects the angle: ${a} ÷ 2 = ${a / 2}.`, {wr: [a, 180 - a, a / 2 + 10, 90 - a / 2], f: deg}); },
    r => mcq(r, 'Which quadrilateral has exactly one pair of parallel sides?', 'trapezium', ['parallelogram', 'rhombus', 'rectangle'], 'A trapezium has one pair of parallel sides. Parallelograms, rhombuses and rectangles have two.'),
    r => mcq(r, 'Which quadrilateral always has diagonals that are equal and bisect each other?', 'rectangle', ['rhombus', 'kite', 'trapezium'], 'The diagonals of a rectangle are equal and bisect each other. A rhombus has diagonals that bisect each other but are not equal.')
  ], word: [
    r => { const a = r.int(55, 80); return N(`A parallelogram-shaped signboard has one angle of ${a}°. Find the size of the angle next to it, in degrees.`, 180 - a, `Adjacent angles add up to 180°: 180 − ${a} = ${180 - a}.`, {wr: [a, 360 - a, 90, 180 - a + 10], f: deg}); },
    r => { const s = r.int(5, 14); return N(`A rhombus-shaped picture frame has sides of ${s} cm. A ribbon is stuck along all four sides. Find the length of the ribbon needed, in cm.`, 4 * s, `4 × ${s} = ${4 * s} cm.`, {wr: [2 * s, s * s, 4 * s + 4], f: cm}); },
    r => { const a = r.int(60, 100), b = r.int(70, 110), c = r.int(80, 120); if (a + b + c >= 340) return null; return N(`A plot of land is a quadrilateral. Three of its angles are ${a}°, ${b}° and ${c}°. Find the fourth angle, in degrees.`, 360 - a - b - c, `360 − ${a} − ${b} − ${c} = ${360 - a - b - c}.`, {wr: [a + b + c, 180 - a, 360 - a - b], f: deg}); },
    r => { const d = r.int(10, 26); return N(`A rectangular gate has one diagonal brace of ${d} cm. The other diagonal brace is the same length. Find the total length of both diagonal braces, in cm.`, 2 * d, `Both diagonals of a rectangle are equal: ${d} + ${d} = ${2 * d} cm.`, {wr: [d, d * d, d / 2, d + 2], f: cm}); },
    r => { const B = r.int(80, 120), C = r.int(50, 80), A = 360 - 2 * B - C; if (A <= 20) return null; return N(`A kite has angles B = ${B}° and C = ${C}° with angle D equal to angle B. Find angle A, in degrees.`, A, `A = 360 − ${B} − ${B} − ${C} = ${A}.`, {wr: [360 - B - C, 180 - C, A + 10], f: deg}); }
  ]});

  /* ---- Polygons ---- */
  gyms.push({id: 'G2.2.quadrilaterals-and-other-polygons.2', plain: [
    r => { const n = r.int(5, 12); return N(`Find the sum of the interior angles of a polygon with ${n} sides, in degrees.`, (n - 2) * 180, `Sum = (n − 2) × 180° = (${n} − 2) × 180° = ${(n - 2) * 180}°.`, {wr: [n * 180, (n - 1) * 180, 360, (n - 2) * 180 + 180], f: deg}); },
    r => { const n = r.pick([5, 6, 8, 9, 10, 12]); return N(`Find the size of each interior angle of a regular polygon with ${n} sides, in degrees.`, (n - 2) * 180 / n, `Sum = ${(n - 2) * 180}°. Each angle = ${(n - 2) * 180} ÷ ${n} = ${(n - 2) * 180 / n}°.`, {wr: [360 / n, 180 - (n - 2) * 180 / n + 10, (n - 2) * 180 / n + 10, (n - 2) * 180], f: deg}); },
    r => { const n = r.pick([5, 6, 8, 9, 10, 12, 15, 18, 20, 24]); return N(`Find the size of each exterior angle of a regular polygon with ${n} sides, in degrees.`, 360 / n, `Exterior angles add up to 360°: 360 ÷ ${n} = ${360 / n}°.`, {wr: [180 - 360 / n, 360, (n - 2) * 180 / n, 360 / n + 5], f: deg}); },
    r => { const e = r.pick([30, 36, 40, 45, 60, 72, 90]); return N(`Each exterior angle of a regular polygon is ${e}°. How many sides does the polygon have?`, 360 / e, `Number of sides = 360 ÷ ${e} = ${360 / e}.`, {wr: [180 / e, 360 / e + 1, 360 / e - 1, e]}); },
    r => { const n = r.pick([6, 8, 9, 10, 12, 15, 18, 20]), i = (n - 2) * 180 / n; return N(`Each interior angle of a regular polygon is ${i}°. How many sides does it have?`, n, `Exterior angle = 180 − ${i} = ${180 - i}°. Number of sides = 360 ÷ ${180 - i} = ${n}.`, {wr: [n + 1, n - 1, 360 / i | 0, (180 - i)]}); },
    r => { const n = r.int(5, 14); return N(`How many diagonals does a polygon with ${n} sides have?`, n * (n - 3) / 2, `Diagonals = n(n − 3) ÷ 2 = ${n} × ${n - 3} ÷ 2 = ${n * (n - 3) / 2}.`, {wr: [n * (n - 3), n * (n - 1) / 2, n - 3, n * (n - 3) / 2 + n]}); },
    r => { const n = r.int(5, 20); return N(`The sum of the interior angles of a polygon is ${(n - 2) * 180}°. How many sides does the polygon have?`, n, `(n − 2) × 180 = ${(n - 2) * 180}, so n − 2 = ${n - 2} and n = ${n}.`, {wr: [n - 2, n + 1, n - 1, n + 2]}); },
    r => { const a = [r.int(90, 130), r.int(100, 140), r.int(90, 140), r.int(100, 150), r.int(100, 140)], s = a.reduce((x, y) => x + y, 0); if (720 - s < 60 || 720 - s > 170) return null; return N(`Five interior angles of a hexagon are ${a.join('°, ')}°. Find the sixth angle, in degrees.`, 720 - s, `Interior angles of a hexagon add up to 720°: 720 − ${s} = ${720 - s}.`, {wr: [s - 360, 540 - s + 100, 720 - s + 10, 360 - s + 360 - 10], f: deg}); },
    r => mcq(r, 'What is a polygon with 8 sides called?', 'octagon', ['hexagon', 'pentagon', 'decagon'], 'A polygon with 8 sides is an octagon.'),
    r => mcq(r, 'What is a polygon with 6 sides called?', 'hexagon', ['pentagon', 'octagon', 'heptagon'], 'A polygon with 6 sides is a hexagon.')
  ], word: [
    r => { const n = r.pick([6, 8, 9, 10, 12]); return N(`A tile is the shape of a regular polygon with ${n} sides. Find the size of each interior angle, in degrees.`, (n - 2) * 180 / n, `(${n} − 2) × 180 ÷ ${n} = ${(n - 2) * 180 / n}°.`, {wr: [360 / n, (n - 2) * 180, (n - 2) * 180 / n + 10], f: deg}); },
    r => { const e = r.pick([30, 36, 45, 60, 72]); return N(`A garden is a regular polygon. At each corner the exterior angle is ${e}°. How many corners does the garden have?`, 360 / e, `360 ÷ ${e} = ${360 / e}.`, {wr: [180 / e, 360 / e + 1, 360 / e - 1, e]}); },
    r => { const n = r.int(6, 12); return N(`${n} friends sit at the corners of a table in the shape of a regular polygon. Each friend shakes hands with everyone who is not a neighbour. How many such handshakes happen? (Count each handshake once.)`, n * (n - 3) / 2, `This is the number of diagonals: ${n} × ${n - 3} ÷ 2 = ${n * (n - 3) / 2}.`, {wr: [n * (n - 3), n * (n - 1) / 2, n, n * (n - 3) / 2 + n]}); },
    r => { const n = r.pick([5, 6, 8, 10]), s = r.int(3, 9); return N(`A regular polygon has ${n} sides, each ${s} cm long. Find its perimeter, in cm.`, n * s, `Perimeter = ${n} × ${s} = ${n * s} cm.`, {wr: [n + s, n * s + n, 2 * n * s, (n - 1) * s], f: cm}); },
    r => { const n = r.pick([6, 8, 9, 12]); return N(`A stop sign is a regular octagon. Find the sum of its interior angles, in degrees.`, 1080, `(8 − 2) × 180 = 1080°.`, {wr: [1440, 360, 900, 1260], f: deg}); }
  ]});

  /* ---- Construction of triangles and quadrilaterals ---- */
  gyms.push({id: 'G2.2.quadrilaterals-and-other-polygons.3', plain: [
    r => { const a = r.int(4, 9), b = a + r.int(2, 5); return N(`Two sides of a triangle are ${a} cm and ${b} cm. The third side is a whole number of cm. What is the greatest possible length of the third side, in cm?`, a + b - 1, `The third side must be less than ${a} + ${b} = ${a + b}, so the greatest whole number is ${a + b - 1}.`, {wr: [a + b, b - a, a + b - 2, b]}); },
    r => { const a = r.int(4, 9), b = a + r.int(2, 5); return N(`Two sides of a triangle are ${a} cm and ${b} cm. The third side is a whole number of cm. What is the least possible length of the third side, in cm?`, b - a + 1, `The third side must be more than ${b} − ${a} = ${b - a}, so the least whole number is ${b - a + 1}.`, {wr: [b - a, a, b - a + 2, 1]}); },
    r => { const a = r.int(4, 9), b = a + r.int(2, 5); return N(`Two sides of a triangle are ${a} cm and ${b} cm. How many whole-number lengths are possible for the third side?`, 2 * a - 1, `The third side lies between ${b - a} and ${a + b} cm, so the whole numbers are ${b - a + 1} to ${a + b - 1}. That is ${2 * a - 1} lengths.`, {wr: [2 * a, a + b - 1, b - a, 2 * a - 2]}); },
    r => { const a = r.int(40, 110) * 2 / 2 | 0; const x = a - a % 2; return N(`An angle of ${x}° is bisected with a pair of compasses. Find the size of each half, in degrees.`, x / 2, `Bisecting gives two equal angles: ${x} ÷ 2 = ${x / 2}.`, {wr: [x, 180 - x, x / 2 + 10, x / 4], f: deg}); },
    r => { const l = r.int(5, 20) * 2; return N(`A line segment of ${l} cm is bisected perpendicularly. Find the distance from one end to the midpoint, in cm.`, l / 2, `The midpoint is halfway: ${l} ÷ 2 = ${l / 2} cm.`, {wr: [l, l / 4, l / 2 + 1, 2 * l], f: cm}); },
    r => { const A = r.int(40, 80), B = r.int(50, 90); return N(`Triangle ABC is constructed with AB = 7 cm, angle A = ${A}° and angle B = ${B}°. Find angle C, in degrees.`, 180 - A - B, `Angles in a triangle add up to 180°: 180 − ${A} − ${B} = ${180 - A - B}.`, {wr: [A + B, 360 - A - B, 180 - A, 90], f: deg}); },
    r => { const a = r.int(80, 100), b = r.int(80, 100), c = r.int(60, 110); return N(`A quadrilateral is constructed with angles ${a}°, ${b}° and ${c}°. Find the fourth angle, in degrees.`, 360 - a - b - c, `Angles in a quadrilateral add up to 360°: 360 − ${a} − ${b} − ${c} = ${360 - a - b - c}.`, {wr: [a + b + c, 180 - a, 360 - a - b], f: deg}); },
    r => { const s = r.int(4, 9); return N(`An equilateral triangle of side ${s} cm is constructed. Find the size of each angle, in degrees.`, 60, 'The three angles of an equilateral triangle are equal and add up to 180°, so each is 60°.', {wr: [90, 45, 30, 180], f: deg}); },
    r => { const a = r.int(3, 6), b = r.int(a + 1, a + 4), c = a + b + r.int(1, 4); return mcq(r, `Which statement is true about a triangle with sides ${a} cm, ${b} cm and ${c} cm?`, 'It cannot be constructed', ['It can be constructed', 'It is an isosceles triangle', 'It is an equilateral triangle'], `${a} + ${b} = ${a + b}, which is less than ${c}. The two shorter sides are too short to meet.`); },
    r => { const a = r.int(5, 8), b = a + r.int(1, 3), c = r.int(b - a + 1, a + b - 1); return mcq(r, `Which statement is true about a triangle with sides ${a} cm, ${b} cm and ${c} cm?`, 'It can be constructed', ['It cannot be constructed', 'It has a right angle', 'It is equilateral'], `The sum of any two sides is greater than the third: ${a} + ${b} > ${c} and the others also hold.`); }
  ], word: [
    r => { const a = r.int(5, 9), b = a + r.int(3, 6); return N(`A triangular garden has two sides of ${a} m and ${b} m. The third side is a whole number of metres. What is the greatest possible length of the third side, in m?`, a + b - 1, `The third side must be less than ${a + b}, so the greatest whole number is ${a + b - 1} m.`, {wr: [a + b, b - a, a + b - 2], f: m}); },
    r => { const a = r.int(5, 9), b = a + r.int(3, 6); return N(`A triangular sail has two sides of ${a} m and ${b} m. The third side is a whole number of metres. What is the least possible length of the third side, in m?`, b - a + 1, `The third side must be more than ${b - a}, so the least whole number is ${b - a + 1} m.`, {wr: [b - a, a, b - a + 2], f: m}); },
    r => { const a = r.int(5, 8), b = a + r.int(2, 4); return N(`A triangular frame has two sides of ${a} cm and ${b} cm. The third side is a whole number of cm. How many different frames can be made?`, 2 * a - 1, `The third side is between ${b - a} and ${a + b}, giving whole numbers ${b - a + 1} to ${a + b - 1}. That is ${2 * a - 1} frames.`, {wr: [2 * a, a + b - 1, b - a, 2 * a - 2]}); },
    r => { const x = r.int(2, 8) * 20; return N(`A student constructs a triangle with angles ${x / 2}° and ${x / 2 + 10}°. Find the third angle, in degrees.`, 180 - x - 10, `180 − ${x / 2} − ${x / 2 + 10} = ${180 - x - 10}.`, {wr: [x + 10, 360 - x - 10, 180 - x / 2], f: deg}); },
    r => { const l = r.int(5, 15) * 2; return N(`A student draws a line ${l} cm long and constructs its perpendicular bisector. How far from each end of the line does the bisector cross it, in cm?`, l / 2, `The bisector crosses at the midpoint: ${l} ÷ 2 = ${l / 2} cm from each end.`, {wr: [l, l / 4, l / 2 + 1, 2 * l], f: cm}); }
  ]});

  /* ---- Congruence ---- */
  gyms.push({id: 'G2.2.congruence-and-similarity.1', plain: [
    r => { const x = r.int(3, 12), a = r.int(1, 6), k = r.int(2, 4); return N(`Triangles ABC and PQR are congruent, with AB = PQ. AB = $(${k}x + ${a})$ cm and PQ = ${k * x + a} cm. Find $x$.`, x, `Corresponding sides are equal: ${k}x + ${a} = ${k * x + a}, so ${k}x = ${k * x} and x = ${x}.`, {wr: [k * x + a, x + 1, x - 1, a]}); },
    r => { const y = r.int(10, 40), k = r.int(2, 4); return N(`Triangles ABC and PQR are congruent. Angle B = $(${k}y)°$ and angle Q = ${k * y}°. Find $y$.`, y, `Corresponding angles are equal: ${k}y = ${k * y}, so y = ${y}.`, {wr: [k * y, y + 1, y - 1, 180 - k * y]}); },
    r => { const a = r.int(5, 12), b = r.int(6, 14), c = r.int(7, 15); return N(`Triangle ABC has sides ${a} cm, ${b} cm and ${c} cm. Triangle PQR is congruent to it. Find the perimeter of triangle PQR, in cm.`, a + b + c, `Congruent triangles have the same sides: ${a} + ${b} + ${c} = ${a + b + c} cm.`, {wr: [2 * (a + b + c), a + b, a * b * c, a + b + c + 1], f: cm}); },
    r => { const A = r.int(40, 80), B = r.int(50, 90); return N(`Triangle ABC has angles A = ${A}° and B = ${B}°. Triangle PQR is congruent to ABC with P = A and Q = B. Find angle R, in degrees.`, 180 - A - B, `R = C = 180 − ${A} − ${B} = ${180 - A - B}.`, {wr: [A + B, 360 - A - B, 180 - A, 90], f: deg}); },
    r => { const s = r.int(4, 9), h = r.int(3, 8); return N(`Two congruent triangles each have base ${2 * s} cm and height ${h} cm. Find the total area of both triangles, in cm².`, 2 * s * h, `Each area = ½ × ${2 * s} × ${h} = ${s * h} cm². Two triangles: ${2 * s * h} cm².`, {wr: [s * h, 4 * s * h, 2 * s * h + 2 * s], f: cm2}); },
    r => { const a = r.int(5, 12), b = r.int(5, 12); return N(`Triangle ABC is congruent to triangle PQR. AB = ${a} cm, BC = ${b} cm and PQ = AB. Find QR, in cm.`, b, `Corresponding sides are equal, so QR = BC = ${b} cm.`, {wr: [a, a + b, b + 1, a * b], f: cm}); },
    r => { const p = r.int(30, 80); return N(`Two congruent triangles ABC and DEF have angle A = ${p}° and DF = AC. Find angle D, in degrees.`, p, 'Congruent triangles have equal corresponding angles, so D = A.', {wr: [180 - p, 90 - p < 0 ? p - 90 : 90 - p, 2 * p, p + 10], f: deg}); },
    r => mcq(r, 'Two triangles have all three pairs of sides equal. Which test shows that they are congruent?', 'SSS', ['SAS', 'AAA', 'RHS'], 'Three pairs of equal sides is the SSS test.'),
    r => mcq(r, 'Two triangles have two pairs of equal sides and the angles between those sides are equal. Which test shows that they are congruent?', 'SAS', ['SSS', 'ASA', 'AAA'], 'Two sides and the included angle equal is the SAS test.'),
    r => mcq(r, 'Which of the following is NOT a test for congruent triangles?', 'AAA', ['SSS', 'SAS', 'ASA'], 'Three equal angles only show the triangles have the same shape, not the same size.')
  ], word: [
    r => { const a = r.int(5, 12), b = r.int(6, 14), c = r.int(7, 15); return N(`Two congruent triangular flags each have sides ${a} cm, ${b} cm and ${c} cm. A border is sewn round both flags. Find the total length of the border, in cm.`, 2 * (a + b + c), `One flag: ${a} + ${b} + ${c} = ${a + b + c} cm. Both: ${2 * (a + b + c)} cm.`, {wr: [a + b + c, a * b * c, a + b + c + 2], f: cm}); },
    r => { const s = r.int(4, 10), h = r.int(4, 9); return N(`Two congruent triangular tiles have a base of ${2 * s} cm and a height of ${h} cm. Find the area of one tile, in cm².`, s * h, `Area = ½ × ${2 * s} × ${h} = ${s * h} cm².`, {wr: [2 * s * h, s * h + h, s + h], f: cm2}); },
    r => { const A = r.int(40, 70), B = r.int(50, 80); return N(`Two congruent triangular road signs have angles ${A}° and ${B}°. Find the third angle of each sign, in degrees.`, 180 - A - B, `180 − ${A} − ${B} = ${180 - A - B}.`, {wr: [A + B, 360 - A - B, 90], f: deg}); },
    r => { const a = r.int(6, 15), x = r.int(2, 5); return N(`Triangle ABC is congruent to triangle PQR. AC = $(${x}n + ${a})$ cm and PR = ${x * 4 + a} cm. Find $n$.`, 4, `Corresponding sides are equal: ${x}n + ${a} = ${x * 4 + a}, so ${x}n = ${x * 4} and n = 4.`, {wr: [x, 4 + x, 3, a]}); }
  ]});

  /* ---- Similarity ---- */
  gyms.push({id: 'G2.2.congruence-and-similarity.2', plain: [
    r => { const k = r.pick([2, 3, 4, 5]), a = r.int(3, 9), b = r.int(4, 11); return N(`Triangles ABC and PQR are similar. AB = ${a} cm and PQ = ${a * k} cm. BC = ${b} cm. Find QR, in cm.`, b * k, `The scale factor is ${a * k} ÷ ${a} = ${k}. QR = ${b} × ${k} = ${b * k} cm.`, {wr: [b + k, b * k + k, a * k, b * k - 1], f: cm}); },
    r => { const k = r.pick([2, 3, 4]), a = r.int(2, 6); return N(`Two similar figures have lengths in the ratio 1 : ${k}. The smaller figure has an area of ${a * 10} cm². Find the area of the larger figure, in cm².`, a * 10 * k * k, `Area ratio = ${k}² = ${k * k}. Area = ${a * 10} × ${k * k} = ${a * 10 * k * k} cm².`, {wr: [a * 10 * k, a * 10 * k * k * k, a * 10 + k * k, a * 10 * (k + 1)], f: cm2}); },
    r => { const k = r.pick([2, 3, 4]), a = r.int(2, 5); return N(`Two similar solids have lengths in the ratio 1 : ${k}. The smaller solid has a volume of ${a * 10} cm³. Find the volume of the larger solid, in cm³.`, a * 10 * k ** 3, `Volume ratio = ${k}³ = ${k ** 3}. Volume = ${a * 10} × ${k ** 3} = ${a * 10 * k ** 3} cm³.`, {wr: [a * 10 * k, a * 10 * k * k, a * 10 + k ** 3, a * 10 * (k + 1)]}); },
    r => { const k = r.pick([2, 3, 4, 5]), A = r.int(2, 6) * k * k; return N(`Two similar figures have areas ${A} cm² and ${A * 4} cm². The smaller figure has a side of ${k * 3} cm. Find the corresponding side of the larger figure, in cm.`, k * 6, `Area ratio = 4, so the length ratio = 2. The side is ${k * 3} × 2 = ${k * 6} cm.`, {wr: [k * 12, k * 3 * 4, k * 3 + 2, k * 3 + 4], f: cm}); },
    r => { const a = r.int(3, 8), k = r.pick([2, 3]), A = r.int(2, 5) * 9; return N(`Two similar triangles have areas in the ratio ${1} : ${k * k}. A side of the smaller triangle is ${a} cm. Find the corresponding side of the larger triangle, in cm.`, a * k, `Length ratio = √${k * k} = ${k}. The side is ${a} × ${k} = ${a * k} cm.`, {wr: [a * k * k, a + k, a * k + k, a * (k + 1)], f: cm}); },
    r => { const k = r.pick([2, 3, 4]), a = r.int(4, 9), b = r.int(2, 6); return N(`Rectangle A is ${a} cm by ${b} cm. Rectangle B is similar to A and its longer side is ${a * k} cm. Find the length of the shorter side of rectangle B, in cm.`, b * k, `Scale factor = ${a * k} ÷ ${a} = ${k}. Shorter side = ${b} × ${k} = ${b * k} cm.`, {wr: [b + k, b * k + 1, a * k, b * k - 1], f: cm}); },
    r => { const k = r.pick([2, 3, 5]), x = r.int(3, 9); return N(`The scale factor from a small figure to a large figure is ${k}. A side of the large figure is ${x * k} cm. Find the corresponding side of the small figure, in cm.`, x, `Small side = ${x * k} ÷ ${k} = ${x} cm.`, {wr: [x * k * k, x + k, x * k, x - 1], f: cm}); },
    r => mcq(r, 'Two similar figures have corresponding sides in the ratio 2 : 5. What is the ratio of their areas?', '4 : 25', ['2 : 5', '8 : 125', '4 : 5'], 'The ratio of areas is the square of the ratio of lengths: 2² : 5² = 4 : 25.'),
    r => mcq(r, 'Two similar solids have corresponding lengths in the ratio 2 : 3. What is the ratio of their volumes?', '8 : 27', ['4 : 9', '2 : 3', '6 : 9'], 'The ratio of volumes is the cube of the ratio of lengths: 2³ : 3³ = 8 : 27.')
  ], word: [
    r => { const h = r.pick([1.5, 1.2, 2]), s = r.pick([2.5, 2, 3]), S = r.pick([10, 12, 15, 20]); const H = h * S / s; if (H !== Math.round(H * 10) / 10) return null; return N(`A pole ${h} m tall casts a shadow ${s} m long. At the same time, a tree casts a shadow ${S} m long. Find the height of the tree, in m.`, H, `Heights are in proportion to shadow lengths: ${h} ÷ ${s} = H ÷ ${S}, so H = ${H} m.`, {wr: [h + S - s, H + 1, S * s, H - 1], f: m}); },
    r => { const k = r.pick([2, 3, 4]), A = r.int(2, 6) * 5; return N(`A small photo has an area of ${A} cm². It is enlarged so that every length is ${k} times as long. Find the area of the enlarged photo, in cm².`, A * k * k, `Area scale factor = ${k}² = ${k * k}. Area = ${A} × ${k * k} = ${A * k * k} cm².`, {wr: [A * k, A * k * k * k, A + k * k, A * (k + 1)], f: cm2}); },
    r => { const k = r.pick([2, 3]), V = r.int(2, 6) * 10; return N(`A small tin has a volume of ${V} cm³. A similar large tin has every length ${k} times as long. Find the volume of the large tin, in cm³.`, V * k ** 3, `Volume scale factor = ${k}³ = ${k ** 3}. Volume = ${V} × ${k ** 3} = ${V * k ** 3} cm³.`, {wr: [V * k, V * k * k, V + k ** 3, V * (k + 1)], f: U('cm³')}); },
    r => { const k = r.pick([2, 3]), b = r.int(3, 8), a = b + r.int(1, 4); return N(`A flag measures ${a} cm by ${b} cm. A similar flag has a shorter side of ${b * k} cm. Find the longer side of the larger flag, in cm.`, a * k, `Scale factor = ${b * k} ÷ ${b} = ${k}. Longer side = ${a} × ${k} = ${a * k} cm.`, {wr: [a + k, a * k + k, b * k, a * k - 1], f: cm}); },
    r => { const s = r.pick([2, 3]), b = r.int(2, 5) * 6; return N(`Two similar triangular sails have areas of ${b} m² and ${b * s * s} m². The smaller sail has a base of ${s * 2} m. Find the base of the larger sail, in m.`, s * s * 2, `Area ratio = ${s * s}, so the length ratio = ${s}. Base = ${s * 2} × ${s} = ${s * s * 2} m.`, {wr: [s * 2 * s * s, s * 2 + s, s * 2], f: m}); }
  ]});

  /* ---- Map scale ---- */
  gyms.push({id: 'G2.2.congruence-and-similarity.3', plain: [
    r => { const d = r.int(2, 9), s = r.pick([10000, 20000, 25000, 50000, 100000]); return N(`A map has a scale of 1 : ${sp(s)}. Two towns are ${d} cm apart on the map. Find the actual distance between the towns, in km.`, d * s / 100000, `Actual distance = ${d} × ${sp(s)} cm = ${sp(d * s)} cm = ${d * s / 100000} km.`, {wr: [d * s / 1000, d * s / 10000, d * s, d * s / 100], f: km}); },
    r => { const k = r.int(2, 8), s = r.pick([25000, 50000, 100000]); const d = k * s / 100000 * 100000 / s; return N(`A map has a scale of 1 : ${sp(s)}. A road is ${k * s / 100000 * 2} km long. Find its length on the map, in cm.`, k * 2, `${k * s / 100000 * 2} km = ${sp(k * s / 100000 * 2 * 100000)} cm. On the map: ${sp(k * s / 100000 * 2 * 100000)} ÷ ${sp(s)} = ${k * 2} cm.`, {wr: [k, k * 20, k * 2 + 1, k * 4]}); },
    r => { const k = r.pick([2, 5, 10]), d = r.int(2, 9) + 0.5; return N(`A map scale is 1 cm : ${k} km. A lake is ${d} cm long on the map. Find its actual length, in km.`, d * k, `${d} × ${k} = ${d * k} km.`, {wr: [d + k, d * k * 10, d / k, d * k + k], f: km}); },
    r => { const a = r.pick([2, 3, 4, 5, 6]), s = r.pick([20000, 25000, 50000]); return N(`On a map, ${a} cm represents ${a * s / 100000} km. The scale is 1 : n. Find $n$.`, s, `${a * s / 100000} km = ${a * s} cm, so 1 cm represents ${s} cm and n = ${s}.`, {wr: [s / 10, s * 10, a * s, s + 1000]}); },
    r => { const s = r.pick([10000, 20000, 50000]), x = r.int(2, 6); return N(`A map has a scale of 1 : ${sp(s)}. A square park is ${x} cm by ${x} cm on the map. Find the actual area of the park, in m².`, x * x * (s / 100) ** 2, `Each side is ${x} × ${sp(s)} = ${sp(x * s)} cm = ${x * s / 100} m. Area = ${x * s / 100}² = ${sp(x * x * (s / 100) ** 2)} m².`, {wr: [x * x * s / 100, x * s / 100, x * x * s, (x * s / 100) * 2], f: U('m²')}); },
    r => { const s = r.pick([50000, 100000]), d = r.int(2, 8); return N(`A map has a scale of 1 : ${sp(s)}. Find the actual distance, in metres, represented by ${d} cm on the map.`, d * s / 100, `${d} × ${sp(s)} = ${sp(d * s)} cm = ${sp(d * s / 100)} m.`, {wr: [d * s / 1000, d * s, d * s / 10, d * s / 100000], f: m}); },
    r => { const s = r.pick([20000, 25000, 50000]), k = r.int(2, 6); return N(`A scale drawing uses a scale of 1 : ${sp(s)}. An actual length of ${k * s / 100} m is shown. How long is it on the drawing, in cm?`, k, `${k * s / 100} m = ${sp(k * s)} cm. On the drawing: ${sp(k * s)} ÷ ${sp(s)} = ${k} cm.`, {wr: [k * 10, k + 1, k * 100, k / 10]}); },
    r => { const k = r.int(2, 5); return mcq(r, `A map scale is 1 cm : ${k} km. What is this scale in the form 1 : n?`, `1 : ${sp(k * 100000)}`, [`1 : ${sp(k * 1000)}`, `1 : ${sp(k * 10000)}`, `1 : ${sp(k * 1000000)}`, `1 : ${sp(k)}`], `${k} km = ${sp(k * 100000)} cm, so the scale is 1 : ${sp(k * 100000)}.`); },
    r => { const s = r.pick([10000, 50000]); return mcq(r, `On a map with a scale of 1 : ${sp(s)}, 1 cm on the map represents how many metres on the ground?`, `${sp(s / 100)} m`, [`${sp(s)} m`, `${sp(s / 1000)} m`, `${sp(s / 10)} m`], `1 cm represents ${sp(s)} cm = ${sp(s / 100)} m.`); }
  ], word: [
    r => { const d = r.int(3, 9), s = r.pick([20000, 25000, 50000]); return N(`On a map with scale 1 : ${sp(s)}, the distance from a school to a park is ${d} cm. Find the actual distance, in km.`, d * s / 100000, `${d} × ${sp(s)} = ${sp(d * s)} cm = ${d * s / 100000} km.`, {wr: [d * s / 1000, d * s / 10000, d * s, d * s / 100], f: km}); },
    r => { const k = r.pick([2, 5]), d = r.int(5, 12); return N(`A hiking map has a scale of 1 cm : ${k} km. A trail is ${d} cm long on the map. How many km is the actual trail?`, d * k, `${d} × ${k} = ${d * k} km.`, {wr: [d + k, d * k * 10, d / k, d * k + k], f: km}); },
    r => { const s = r.pick([20000, 50000]), km_ = r.int(2, 6); return N(`A walking route is ${km_} km long. On a map with scale 1 : ${sp(s)}, how long is the route in cm?`, km_ * 100000 / s, `${km_} km = ${sp(km_ * 100000)} cm. On the map: ${sp(km_ * 100000)} ÷ ${sp(s)} = ${km_ * 100000 / s} cm.`, {wr: [km_ * 1000 / s, km_ * 100000 / s * 10, km_ * 100000, km_ * 100000 / s + 1]}); },
    r => { const s = r.pick([25000, 50000]), x = r.int(2, 4); return N(`On a map with scale 1 : ${sp(s)}, a rectangular field measures ${x} cm by ${x * 2} cm. Find the actual length of the longer side, in metres.`, x * 2 * s / 100, `${x * 2} × ${sp(s)} = ${sp(x * 2 * s)} cm = ${sp(x * 2 * s / 100)} m.`, {wr: [x * s / 100, x * 2 * s / 1000, x * 2 * s, x * 2 * s / 100 + 100], f: m}); }
  ]});

  /* ---- Pythagoras' theorem ---- */
  gyms.push({id: 'G2.2.pythagoras-theorem.1', plain: [
    r => { const [a, b, c] = tri(r); return N(`A right-angled triangle has shorter sides of ${a} cm and ${b} cm. Find the length of the hypotenuse, in cm.`, c, `c² = ${a}² + ${b}² = ${a * a} + ${b * b} = ${c * c}, so c = ${c}.`, {wr: [a + b, c * c, b - a, c + 1], f: cm}); },
    r => { const [a, b, c] = tri(r); return N(`A right-angled triangle has a hypotenuse of ${c} cm and one other side of ${a} cm. Find the third side, in cm.`, b, `b² = ${c}² − ${a}² = ${c * c} − ${a * a} = ${b * b}, so b = ${b}.`, {wr: [c - a, c + a, b * b, b + 1], f: cm}); },
    r => { const [a, b, c] = tri(r); return N(`A right-angled triangle has sides ${a} cm, ${b} cm and ${c} cm (the hypotenuse). Find its area, in cm².`, a * b / 2, `Area = ½ × ${a} × ${b} = ${a * b / 2} cm².`, {wr: [a * b, a + b + c, c * c / 2, a * b / 2 + a], f: cm2}); },
    r => { const [a, b, c] = tri(r); return N(`A right-angled triangle has sides ${a} cm, ${b} cm and ${c} cm (the hypotenuse). Find its perimeter, in cm.`, a + b + c, `${a} + ${b} + ${c} = ${a + b + c} cm.`, {wr: [a + b, a * b / 2, 2 * (a + b), a + b + c + 1], f: cm}); },
    r => { const [a, b, c] = tri(r); return N(`A rectangle has sides ${a} cm and ${b} cm. Find the length of its diagonal, in cm.`, c, `Diagonal² = ${a}² + ${b}² = ${c * c}, so the diagonal is ${c} cm.`, {wr: [a + b, c * c, b - a, c + 1], f: cm}); },
    r => { const k = r.int(1, 5), h = 12 * k, hb = 5 * k; return N(`An isosceles triangle has two sides of ${13 * k} cm and a base of ${2 * hb} cm. Find its height, in cm.`, h, `The height meets the base at its midpoint, ${hb} cm from each end. h² = ${13 * k}² − ${hb}² = ${h * h}, so h = ${h}.`, {wr: [13 * k - hb, 13 * k + hb, h * h, h + 1], f: cm}); },
    r => { const [a, b, c] = tri(r); return N(`In triangle ABC, angle B = 90°, AB = ${a} cm and BC = ${b} cm. Find AC, in cm.`, c, `AC² = ${a}² + ${b}² = ${c * c}, so AC = ${c} cm.`, {wr: [a + b, c * c, b - a, c + 2], f: cm}); },
    r => { const [a, b, c] = tri(r); return mcq(r, `Which of the following could be the sides of a right-angled triangle?`, `${a} cm, ${b} cm, ${c} cm`, [`${a} cm, ${b} cm, ${c + 1} cm`, `${a} cm, ${b + 1} cm, ${c} cm`, `${a + 1} cm, ${b} cm, ${c} cm`], `${a}² + ${b}² = ${a * a + b * b} = ${c}², so these sides satisfy Pythagoras' theorem.`); },
    r => { const [a, b, c] = tri(r); return mcq(r, `A triangle has sides ${a} cm, ${b} cm and ${c + 1} cm. Is it right-angled?`, 'No, because the squares of the two shorter sides do not add to the square of the longest side', ['Yes, because the sides are whole numbers', `Yes, because ${a} + ${b} > ${c + 1}`, 'Yes, because it has three different sides'], `${a}² + ${b}² = ${a * a + b * b}, but ${(c + 1)}² = ${(c + 1) ** 2}. They are not equal, so the triangle is not right-angled.`); }
  ], word: [
    r => { const [a, b, c] = tri(r); return N(`A ladder ${c} m long leans against a vertical wall. Its foot is ${a} m from the wall. How high up the wall does the ladder reach, in m?`, b, `Height² = ${c}² − ${a}² = ${b * b}, so the height is ${b} m.`, {wr: [c - a, c + a, b * b, b + 1], f: m}); },
    r => { const [a, b, c] = tri(r); return N(`A rectangular field is ${a} m long and ${b} m wide. Find the length of its diagonal, in m.`, c, `Diagonal² = ${a}² + ${b}² = ${c * c}, so the diagonal is ${c} m.`, {wr: [a + b, c * c, b - a, c + 1], f: m}); },
    r => { const [a, b, c] = tri(r); return N(`A hiker walks ${a} km east and then ${b} km north. How far is the hiker from the starting point in a straight line, in km?`, c, `Distance² = ${a}² + ${b}² = ${c * c}, so the distance is ${c} km.`, {wr: [a + b, c * c, b - a, c + 1], f: km}); },
    r => { const [a, b, c] = tri(r); return N(`A kite string is ${c} m long. The kite is directly above a point on the ground ${a} m from the person. How high above the ground is the kite, in m? (Ignore the height of the person.)`, b, `Height² = ${c}² − ${a}² = ${b * b}, so the height is ${b} m.`, {wr: [c - a, c + a, b * b, b + 1], f: m}); },
    r => { const [a, b, c] = tri(r); return N(`A TV screen is ${a} cm wide and ${b} cm high. Find the length of its diagonal, in cm.`, c, `Diagonal² = ${a}² + ${b}² = ${c * c}, so the diagonal is ${c} cm.`, {wr: [a + b, c * c, b - a, c + 1], f: cm}); }
  ]});

  /* ---- Pythagoras in the real world ---- */
  gyms.push({id: 'G2.2.pythagoras-theorem.2', plain: [
    r => { const [a, b, c] = tri(r); return N(`A rope ${c} m long is stretched from the top of a vertical pole to the ground ${a} m from the foot of the pole. Find the height of the pole, in m.`, b, `Height² = ${c}² − ${a}² = ${b * b}, so the height is ${b} m.`, {wr: [c - a, c + a, b * b, b + 1], f: m}); },
    r => { const [a, b, c] = tri(r); return N(`Two points are ${a} m apart horizontally and ${b} m apart vertically. Find the straight-line distance between them, in m.`, c, `Distance² = ${a}² + ${b}² = ${c * c}, so the distance is ${c} m.`, {wr: [a + b, c * c, b - a, c + 1], f: m}); },
    r => { const [a, b, c] = tri(r); return N(`A ship sails ${a} km due south and then ${b} km due east. How far is the ship from its starting point, in km?`, c, `Distance² = ${a}² + ${b}² = ${c * c}, so the distance is ${c} km.`, {wr: [a + b, c * c, b - a, c + 1], f: km}); },
    r => { const [a, b, c] = tri(r); return N(`A straight road is ${c} km long and climbs ${a} km vertically. Find the horizontal distance covered by the road, in km.`, b, `Horizontal² = ${c}² − ${a}² = ${b * b}, so it is ${b} km.`, {wr: [c - a, c + a, b * b], f: km}); },
    r => { const [a, b, c] = tri(r); return N(`A rectangular painting has a diagonal of ${c} cm and a width of ${a} cm. Find its height, in cm.`, b, `Height² = ${c}² − ${a}² = ${b * b}, so the height is ${b} cm.`, {wr: [c - a, c + a, b * b, b + 1], f: cm}); },
    r => { const [a, b, c] = tri(r); return N(`A support wire ${c} m long is attached to the top of a mast ${b} m tall. How far from the foot of the mast is the wire fixed to the ground, in m?`, a, `Distance² = ${c}² − ${b}² = ${a * a}, so the distance is ${a} m.`, {wr: [c - b, c + b, a * a, a + 1], f: m}); },
    r => { const [a, b, c] = tri(r); return N(`A rectangular park is ${a} m by ${b} m. Anna walks along two sides from one corner to the opposite corner, and Ben walks along the diagonal. How many metres shorter is Ben's path?`, a + b - c, `Anna: ${a} + ${b} = ${a + b} m. Ben: ${c} m. Difference = ${a + b - c} m.`, {wr: [a + b, c, a + b + c, a + b - c + 1], f: m}); },
    r => { const [a, b, c] = tri(r); return mcq(r, `A ladder ${c} m long reaches ${b} m up a wall. Which expression gives the distance of its foot from the wall?`, `$\\sqrt{${c}^2 - ${b}^2}$`, [`$\\sqrt{${c}^2 + ${b}^2}$`, `$${c} - ${b}$`, `$${c} + ${b}$`], 'The ladder is the hypotenuse, so the distance is √(c² − b²).'); },
    r => { const [a, b, c] = tri(r); return mcq(r, `A hiker walks ${a} km north then ${b} km east. Which expression gives the straight-line distance back to the start?`, `$\\sqrt{${a}^2 + ${b}^2}$`, [`$${a} + ${b}$`, `$\\sqrt{${a}^2 - ${b}^2}$`, `$${a} \\times ${b}$`], 'The straight-line distance is the hypotenuse: √(a² + b²).'); }
  ], word: [
    r => { const [a, b, c] = tri(r); return N(`A ladder ${c} m long reaches a window ${b} m above the ground. How far is the foot of the ladder from the wall, in m?`, a, `Distance² = ${c}² − ${b}² = ${a * a}, so the foot is ${a} m from the wall.`, {wr: [c - b, c + b, a * a, a + 1], f: m}); },
    r => { const [a, b, c] = tri(r); return N(`A rectangular door is ${a} cm wide and ${b} cm high. A diagonal brace is fixed from one corner to the opposite corner. Find the length of the brace, in cm.`, c, `Diagonal² = ${a}² + ${b}² = ${c * c}, so the brace is ${c} cm.`, {wr: [a + b, c * c, b - a, c + 1], f: cm}); },
    r => { const [a, b, c] = tri(r); return N(`A swimmer swims straight across a river ${a} m wide but the current carries the swimmer ${b} m downstream. How far does the swimmer actually travel, in m?`, c, `Distance² = ${a}² + ${b}² = ${c * c}, so the distance is ${c} m.`, {wr: [a + b, c * c, b - a, c + 1], f: m}); },
    r => { const [a, b, c] = tri(r); return N(`A road goes ${a} km east then ${b} km north. A new straight road is built between the ends. How many kilometres shorter is the new road than the old route?`, a + b - c, `Old route = ${a + b} km, new road = ${c} km. Saving = ${a + b - c} km.`, {wr: [a + b, c, a + b + c, a + b - c + 1], f: km}); },
    r => { const [a, b, c] = tri(r); return N(`A flagpole ${b} m tall is held by a wire from its top to the ground ${a} m from its foot. Find the length of the wire, in m.`, c, `Wire² = ${a}² + ${b}² = ${c * c}, so the wire is ${c} m long.`, {wr: [a + b, c * c, b - a, c + 1], f: m}); }
  ]});

  return gyms;
};
